"""Exercise the numeric tuple and Point3D entry points on the frozen SymPy trees."""
import json
from sympy import Plane, Point3D

plane = Plane((0, 0, 0), normal_vector=(0, 0, 1))
inputs = {"tuple_on_plane": (1, 1, 0), "point_on_plane": Point3D(1, 1, 0),
          "point_above_plane": Point3D(1, 1, 2)}
observed = {}
for name, entity in inputs.items():
    try:
        observed[name] = {"value": str(plane.distance(entity))}
    except Exception as exc:
        observed[name] = {"exception": type(exc).__name__, "message": str(exc)}
print(json.dumps(observed, sort_keys=True))
